// errTrail is Unimplemented and not PermissionDenied, and to everybody: it
// is not about who is asking, and no credential changes it.
func errTrail() error {
	return status.Error(codes.Unimplemented,
		"the trail is written by what happened, not by anybody asking")
}

// Recorder writes one row of the trail for every write the generated
// servers make.
//
// It is not a layer and it does not override an Rpc. The servers call it
// from inside the transaction that makes the write, so the row and the
// record of it hold or fall together -- and so every Rpc that changes
// anything is on the trail without anybody having listed them.
//
//	sink, err := bare.NewServer(db, bare.WithRecorder(pd.Recorder()))
func Recorder() bare.Recorder { return recorder{} }

type recorder struct{}

var _ bare.Recorder = recorder{}

// Record writes what happened. It runs inside the write's transaction, so an
// error here takes the write with it -- which is the answer wanted: a write
// that could not be accounted for did not happen.
//
// It writes through the server it was handed, which runs on that transaction
// and does not record; a recorder that recorded its own writes would not
// stop.
func (recorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	// Which entity this is about, before anything decides what of the
	// patch may be kept: a field declared `secret:` belongs to one entity,
	// and the identifier's domain byte is the only thing that says which.
	key, err := audit1.Identifier(c.Key)
	if err != nil {
		return err
	}

	var patch proto.Message
	if v := hidden(key, c.Patch); v != nil {
		patch = v
	}

	v, err := audit1.Of(ctx, c.Method, c.Key, patch)
	if err != nil {
		return err
	}

	// The row this happened to, which is where the object's tenant and the
	// state after the write both come from. Absent for an Erase that took
	// the row with it; see [subject].
	tenant, value, err := subject(ctx, s, v.Object)
	if err != nil {
		return err
	}
	if tenant == uuid.Nil {
		// Nothing to file it under but the actor's own, which is what the
		// trail said for every row before this. It is the honest fallback
		// rather than a zero: a record nobody can read is not a record.
		tenant = uuid.UUID(v.Tenant)
	}

	domain := uint32(v.Object.Domain())

	_, err = s.Audit().Add(ctx, apptest.AuditAddRequest_builder{
		TenantId:            tenant[:],
		ActorTenantId:       v.Tenant.Bytes(),
		ActorId:             v.Actor.Bytes(),
		TraceID:             notNull(v.Trace),
		Action:              v.Action,
		ObjectId:            v.Object.Bytes(),
		Domain:              &domain,
		Patch:               notNull(v.Patch),
		Value:               notNull(value),
		CounterpartTenantId: v.CounterpartBytes(),
	}.Build())

	return err
}

// notNull is `v` as a column that says it always has bytes takes it.
//
// The two drivers disagree about exactly one value: a nil `[]byte` is Sql
// NULL to pgx and an empty blob to SQLite's driver. So a nil bound to a NOT
// NULL column is a write that passes on the database the tests run on and is
// refused by the one the app is deployed on.
//
// Nothing is hidden by it. These columns are NOT NULL, so there is no nil for
// them to mean: an empty `trace_id` is a call nobody traced, an empty `patch`
// is a write that was not compiled from a document, an empty `value` is a row
// that was not there to read. `counterpart_tenant_id` is nullable so that nil
// can say there was no other party, and it does not come through here.
func notNull(v []byte) []byte {
	if v == nil {
		return []byte{}
	}

	return v
}

// hidden is `p` with the entries the schema said are never answered with
// taken out, or nil when there is nothing to record.
//
// Which entity it is comes from the identifier, as everywhere else here: a
// `pdid` carries its domain, so one switch answers it for every entity
// there will ever be.
func hidden(key pdid.Id, p *patchpb.Patch) *patchpb.Patch {
	if p == nil {
		return nil
	}

	var secret []uint32
	switch key.Domain() {
	case RobotDomain:
		secret = []uint32{8}
	case SealDomain:
		secret = []uint32{8}
	}
	if len(secret) == 0 {
		// An entity that declared none, which is nearly all of them.
		return p
	}

	kept := []*patchpb.Entry{}
	for _, e := range p.GetDelta().GetEntries() {
		// Two shapes, because an entry says where it applies in one of
		// two ways: a `path`, which names one place, and `targets`,
		// which is a list of selectors. A generated `Patch` writes the
		// second even for one field, and reading only the first is how
		// this looked like it worked while letting everything through.
		if named(e.GetPath(), secret) {
			continue
		}

		hit := false
		for _, t := range e.GetTargets().GetSelectors() {
			if slices.Contains(secret, t.GetKey().GetField().GetNumber()) {
				hit = true
				break
			}
		}
		if hit {
			continue
		}

		kept = append(kept, e)
	}
	if len(kept) == len(p.GetDelta().GetEntries()) {
		return p
	}

	// A copy, because the document is the caller's and the write below this
	// is still going to apply it.
	out := proto.CloneOf(p)
	out.GetDelta().SetEntries(kept)

	return out
}

// named is whether a path's first segment is one of `ns`.
//
// The first and no other: a deeper segment is inside a message-valued
// field, and a message field cannot be declared `secret:` -- the
// declaration is on the column.
func named(p *patchpb.Path, ns []uint32) bool {
	ss := p.GetSegments()
	if len(ss) == 0 {
		return false
	}

	return slices.Contains(ns, ss[0].GetField().GetNumber())
}

// subject is the tenant of the row `key` names and the row itself, and the
// nil identifier when there is no such row any more.
func subject(ctx context.Context, s bare.Server, key pdid.Id) (uuid.UUID, []byte, error) {
	switch key.Domain() {
	case AuditDomain:
		row, err := s.Audit().Get(ctx, apptest.AuditGetRequest_builder{
			Ref: apptest.AuditRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		k, err := uuid.FromBytes(row.GetTenantId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case CellDomain:
		row, err := s.Cell().Get(ctx, apptest.CellGetRequest_builder{
			Ref: apptest.CellRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		// Erased softly is still a row; see [erasedCell].
		if status.Code(err) == codes.NotFound {
			row, err = erasedCell(ctx, s, key)
		}
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		if !row.HasTenant() {
			return uuid.Nil, b, nil
		}

		k, err := uuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case HolderDomain:
		row, err := s.Holder().Get(ctx, apptest.HolderGetRequest_builder{
			Ref: apptest.HolderRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		// Erased softly is still a row; see [erasedHolder].
		if status.Code(err) == codes.NotFound {
			row, err = erasedHolder(ctx, s, key)
		}
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		if !row.HasTenant() {
			return uuid.Nil, b, nil
		}

		k, err := uuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case JointDomain:
		row, err := s.Joint().Get(ctx, apptest.JointGetRequest_builder{
			Ref: apptest.JointRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		// Erased softly is still a row; see [erasedJoint].
		if status.Code(err) == codes.NotFound {
			row, err = erasedJoint(ctx, s, key)
		}
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		if !row.HasRobot() {
			return uuid.Nil, b, nil
		}

		up, err := pdid.From(row.GetRobot().GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		k, _, err := subject(ctx, s, up)
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case PairingDomain:
		row, err := s.Pairing().Get(ctx, apptest.PairingGetRequest_builder{
			Ref: apptest.PairingRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		if !row.HasLead() {
			return uuid.Nil, b, nil
		}

		up, err := pdid.From(row.GetLead().GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		k, _, err := subject(ctx, s, up)
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case ReadingDomain:
		row, err := s.Reading().Get(ctx, apptest.ReadingGetRequest_builder{
			Ref: apptest.ReadingRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		if !row.HasRobot() {
			return uuid.Nil, b, nil
		}

		up, err := pdid.From(row.GetRobot().GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		k, _, err := subject(ctx, s, up)
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case RobotDomain:
		row, err := s.Robot().Get(ctx, apptest.RobotGetRequest_builder{
			Ref: apptest.RobotRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		// Erased softly is still a row; see [erasedRobot].
		if status.Code(err) == codes.NotFound {
			row, err = erasedRobot(ctx, s, key)
		}
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		hideRobot(row)

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		if !row.HasTenant() {
			return uuid.Nil, b, nil
		}

		k, err := uuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	case TenantDomain:
		row, err := s.Tenant().Get(ctx, apptest.TenantGetRequest_builder{
			Ref: apptest.TenantRef_builder{Id: key.Bytes()}.Build(),
		}.Build())
		if err != nil {
			if status.Code(err) == codes.NotFound {
				return uuid.Nil, []byte{}, nil
			}

			return uuid.Nil, nil, err
		}

		b, err := proto.Marshal(row)
		if err != nil {
			return uuid.Nil, nil, err
		}

		k, err := uuid.FromBytes(row.GetId())
		if err != nil {
			return uuid.Nil, nil, err
		}

		return k, b, nil

	}

	// An entity with no tenant to file under: one declared `global: {}`,
	// which the switch above skips, or a domain nothing registered, which
	// is an identifier from somewhere else. Nothing to read either way.
	return uuid.Nil, []byte{}, nil
}

// erasedCell is the row `key` names among the rows already erased, which no
// bare read answers: erasure is part of every reference that server builds.
// The recorder is the one caller that has to see past it -- the row it asks
// about was erased by the very write it is recording, and a trail row built
// blind was filed under the actor's tenant with an empty value, which the
// tenant whose row was erased could not read.
func erasedCell(ctx context.Context, s bare.Server, key pdid.Id) (*apptest.Cell, error) {
	k, err := uuid.FromBytes(key.Bytes())
	if err != nil {
		return nil, err
	}

	q := s.Db.Cell.Query().Where(cell.IdEQ(k), cell.DateErasedNotNil())
	bare.CellSelectInit(q, nil)

	v, err := q.Only(ctx)
	if err != nil {
		if ent.IsNotFound(err) {
			return nil, status.Error(codes.NotFound, "Cell not found")
		}

		return nil, err
	}

	return v.Proto(), nil
}

